<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue';
import LawsVersion from './LawsVersion.vue';
type Row=Record<string,any>;
const props=defineProps<{endpoint:string}>();
const books=ref<Row[]>([]),selected=ref<Row|null>(null),articles=ref<Row[]>([]),active=ref<number|null>(null),query=ref(''),results=ref<Row[]|null>(null),error=ref(''),busy=ref(false),allowed=ref(true),enabled=ref(true),history=ref<Row[]|null>(null);
const current=computed(()=>articles.value.find(a=>a.id===active.value));
const groups=computed(()=>{const map=new Map<string,Row[]>();for(const a of articles.value){const v=a.current||a.scheduled;const key=v?.chapter||'Allgemeine Bestimmungen';map.set(key,[...(map.get(key)||[]),a]);}return [...map].map(([title,items])=>({title,items}));});
async function api(action:string,q:Row={}){const r=await fetch(props.endpoint+'?'+new URLSearchParams({action,view:'reader',...q}),{credentials:'include',headers:{...(props.endpoint.includes('/social/')?{'X-Social-Account':sessionStorage.getItem('social-account')||'0'}:{})}});const d=await r.json();if(!r.ok)throw Error(d.error||'Gesetze konnten nicht geladen werden.');return d;}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn();}catch(e){error.value=e instanceof Error?e.message:'Anfrage fehlgeschlagen.';}finally{busy.value=false;}}
async function openBook(id:number,article?:number,record=true){const r=await api('book',{id});selected.value=r.book;articles.value=r.articles;active.value=article??r.articles[0]?.id??null;results.value=null;history.value=null;if(record)recordLocation();}
function choose(id:number){active.value=id;history.value=null;recordLocation();}
async function search(){results.value=(await api('search',{q:query.value.trim()})).items;}
function back(){selected.value=null;active.value=null;results.value=null;history.value=null;query.value='';recordLocation();}
const title=(a:Row)=>(a.current||a.scheduled)?.title||'';
function locationFor(book?:number,article?:number){return location.href.split('#')[0]+(location.hash.startsWith('#/') ? '#/laws'+(book?'/book/'+book+(article?'/paragraph/'+article:''):'') : (book?'#law-book-'+book+(article?'-paragraph-'+article:''):''));}
function recordLocation(){const url=locationFor(selected.value?.id,active.value??undefined);if(url!==location.href)window.history.pushState(null,'',url);}
function directLink(id:number){return locationFor(selected.value?.id,id);}
async function restoreLocation(){
 const book=location.hash.match(/(?:#\/laws\/book\/|#law-book-)(\d+)(?:(?:\/paragraph\/|-paragraph-)(\d+))?/);
 if(book){await openBook(Number(book[1]),book[2]?Number(book[2]):undefined,false);return;}
 const legacy=Number(location.hash.match(/(?:#\/laws\/|#law-)(\d+)$/)?.[1]||0);
 if(legacy){for(const b of books.value){const r=await api('book',{id:b.id});if(r.articles.some((a:Row)=>a.id===legacy)){await openBook(b.id,legacy,false);return;}}}
 selected.value=null;active.value=null;results.value=null;history.value=null;
}
const onHistory=()=>run(restoreLocation);
onMounted(()=>{window.addEventListener('popstate',onHistory);window.addEventListener('hashchange',onHistory);run(async()=>{const s=await api('bootstrap');allowed.value=s.can_read;enabled.value=s.enabled;if(!s.enabled||!s.can_read)return;books.value=(await api('books')).items;await restoreLocation();});});
onUnmounted(()=>{window.removeEventListener('popstate',onHistory);window.removeEventListener('hashchange',onHistory);});
</script>
<template>
<section class="law-reader" :aria-busy="busy">
 <header class="reader-heading"><div><span class="reader-eyebrow">GESETZESSAMMLUNG</span><h1>{{selected?.title||'Gesetze'}}</h1><p>{{selected?.description||'Gesetzbuch auswählen, Vorschriften nachschlagen und Änderungen nachvollziehen.'}}</p></div><button v-if="selected" @click="back">← Alle Gesetzbücher</button></header>
 <p v-if="error" role="alert" class="reader-error">{{error}}</p>
 <p v-if="!enabled">Die Gesetze sind derzeit nicht verfügbar.</p><p v-else-if="!allowed">Zum Lesen bitte anmelden.</p>
 <template v-else>
  <form class="reader-search" @submit.prevent="run(search)"><label for="law-global-search">Alle Gesetzbücher durchsuchen</label><div><input id="law-global-search" v-model="query" type="search" maxlength="200" placeholder="Begriff, Paragraph oder Thema eingeben"/><button :disabled="busy||!query.trim()">Suchen</button><button v-if="results!==null" type="button" @click="results=null;query=''">Schließen</button></div></form>
  <section v-if="results!==null" class="reader-results" aria-live="polite"><h2>{{results.length}} Treffer</h2><p v-if="!results.length">Keine passenden Vorschriften gefunden.</p><button v-for="r in results" :key="r.article.id" :disabled="busy" @click="run(()=>openBook(r.book_id,r.article.id))"><small>{{r.book_title}}</small><strong>§ {{r.article.number}} · {{title(r.article)}}</strong></button></section>
  <section v-else-if="!selected" class="reader-library"><div class="library-heading"><h2>Gesetzbücher</h2><span>{{books.length}} verfügbar</span></div><p v-if="!books.length&&!busy">Es wurden noch keine Gesetzbücher angelegt.</p><div class="book-grid"><button v-for="(book,index) in books" :key="book.id" class="book-card" :disabled="busy" @click="run(()=>openBook(book.id))"><span class="book-number">{{String(Number(index)+1).padStart(2,'0')}}</span><h3>{{book.title}}</h3><p>{{book.description||'Vorschriften und veröffentlichte Fassungen'}}</p><span class="book-open">Gesetzbuch öffnen <span>↗</span></span></button></div></section>
  <div v-else class="reader-layout">
   <nav class="reader-toc" aria-label="Inhaltsverzeichnis"><h2>Inhaltsverzeichnis</h2><p v-if="!articles.length">Noch keine veröffentlichten Paragraphen.</p><section v-for="g in groups" :key="g.title"><h3>{{g.title}}</h3><button v-for="a in g.items" :key="a.id" :aria-current="active===a.id?'true':undefined" @click="choose(a.id)"><span>§ {{a.number}}</span>{{title(a)}}</button></section></nav>
   <main class="reader-document"><article v-if="current" :id="'law-'+current.id"><div class="document-label"><span>{{current.current?.chapter||current.scheduled?.chapter||'Vorschrift'}}</span><span>{{current.current?(current.current.repealed_at?'Außer Kraft':'Geltende Fassung'):'Zukünftige Fassung'}}</span></div><h2>§ {{current.number}} · {{title(current)}}</h2><LawsVersion v-if="current.current" :version="current.current" :anchor-prefix="'law-'+current.id"/><p v-if="current.current?.repealed_at">Außer Kraft seit {{current.current.repealed_at}} UTC: {{current.current.repeal_reason}}</p><details v-if="current.scheduled" :open="!current.current"><summary>Gültig ab {{current.scheduled.effective_at}} UTC</summary><LawsVersion :version="current.scheduled"/></details><footer><a :href="directLink(current.id)">Direktlink</a><button :disabled="busy" @click="run(async()=>{history=(await api('history',{id:current!.id})).items;})">Frühere Fassungen</button></footer><section v-if="history" class="reader-history"><h3>Veröffentlichte Fassungen</h3><button @click="history=null">Schließen</button><article v-for="v in history" :key="v.id"><h4>{{v.title}} · {{v.effective_at}} UTC</h4><LawsVersion :version="v"/></article></section></article><div v-else class="reader-empty"><h2>Noch keine veröffentlichten Inhalte</h2><p>Freigegebene Paragraphen erscheinen hier im Gesetzbuch.</p></div></main>
  </div>
 </template>
</section>
</template>
<style scoped>
.law-reader{--law-bg:var(--surface,#fff);--law-text:var(--text,#202c35);--law-line:var(--line,#d7dee2);container:law-reader/inline-size;background:var(--law-bg);color:var(--law-text);max-width:1320px;margin:20px auto;padding:clamp(20px,3vw,40px);border:1px solid var(--law-line);border-radius:16px;box-sizing:border-box;font:inherit}.reader-heading{display:flex;justify-content:space-between;align-items:center;gap:24px;padding-bottom:28px;border-bottom:1px solid var(--law-line)}.reader-eyebrow{font-size:11px;letter-spacing:.16em;opacity:.6}.reader-heading h1{font-size:32px;letter-spacing:-.03em;margin:10px 0}.reader-heading p{max-width:700px;opacity:.65;line-height:1.65;margin:0}.law-reader button,.law-reader input{font:inherit;color:inherit;border:1px solid var(--law-line);border-radius:8px;background:var(--law-bg);padding:10px 14px}.law-reader button{cursor:pointer}.law-reader button:disabled{opacity:.5;cursor:wait}.law-reader button:hover{border-color:var(--brand,#087f80)}.law-reader :focus-visible{outline:2px solid var(--brand,#087f80);outline-offset:3px}.reader-search{margin:24px 0 32px}.reader-search label{display:block;font-size:12px;opacity:.65;margin-bottom:8px}.reader-search>div{display:flex;gap:8px}.reader-search input{min-width:0;flex:1}.library-heading{display:flex;align-items:center;justify-content:space-between;margin:24px 0 16px}.library-heading h2{font-size:18px;margin:0}.library-heading span{font-size:12px;opacity:.6}.book-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,260px),1fr));gap:18px}.law-reader .book-card{text-align:left;padding:24px;display:flex;align-items:stretch;flex-direction:column;min-height:235px;border-radius:12px;box-shadow:0 3px 16px #00000003}.book-number{font-size:12px;color:var(--brand,#087f80)}.book-card h3{font-size:22px;letter-spacing:-.02em;margin:24px 0 8px}.book-card p{font-size:14px;line-height:1.65;opacity:.65;margin:0 0 24px}.book-open{border-top:1px solid var(--law-line);padding-top:16px;margin-top:auto;display:flex;justify-content:space-between;font-size:13px}.reader-layout{display:grid;grid-template-columns:260px minmax(0,1fr);gap:32px}.reader-toc{align-self:start;background:color-mix(in srgb,var(--law-text) 3%,var(--law-bg));padding:20px;border-radius:12px}.reader-toc h2{font-size:13px;letter-spacing:.03em;margin:0 0 24px}.reader-toc h3{font-size:12px;opacity:.6;margin:24px 0 8px}.reader-toc button{display:flex;justify-content:flex-start;gap:10px;width:100%;text-align:left;border:0;font-size:13px;line-height:1.5;margin:3px 0;background:transparent}.reader-toc button span{white-space:nowrap;font-weight:600}.reader-toc [aria-current=true]{background:var(--law-bg);box-shadow:0 2px 8px #00000007;color:var(--brand,#087f80)}.reader-document{min-width:0;border:1px solid var(--law-line);border-radius:12px;padding:32px}.document-label{display:flex;justify-content:space-between;gap:12px;font-size:11px;opacity:.6}.reader-document h2{font-size:27px;letter-spacing:-.025em;line-height:1.4;margin:20px 0 28px}.reader-document footer{display:flex;align-items:center;gap:20px;border-top:1px solid var(--law-line);padding-top:20px;margin-top:32px;font-size:12px}.reader-document a{color:var(--brand,#087f80)}.reader-history{margin-top:24px}.reader-history article{border-bottom:1px solid var(--law-line);padding:16px 0}.reader-results>button{display:flex;flex-direction:column;gap:8px;text-align:left;width:100%;margin:10px 0}.reader-results small{opacity:.6}.reader-error{padding:16px;border:1px solid #b83232;color:#b83232;border-radius:8px}.reader-empty p{line-height:1.7;opacity:.65}@container law-reader (max-width:750px){.reader-layout{grid-template-columns:1fr;gap:16px}.reader-toc{max-height:240px;overflow:auto}.reader-document{padding:20px}.reader-heading{flex-direction:column;align-items:flex-start}.reader-search>div{flex-wrap:wrap}.reader-search input{flex-basis:100%}}@media(prefers-color-scheme:dark){.law-reader{--law-bg:var(--surface,#1b2228);--law-text:var(--text,#ecf0f2);--law-line:var(--line,#3b454e)}}
</style>
